package fpv.render;

import arc.*;import arc.graphics.*;import arc.graphics.g2d.*;import arc.mock.*;import arc.util.*;
import mindustry.*;import mindustry.content.*;import mindustry.game.*;import mindustry.gen.*;import mindustry.world.*;import mindustry.world.blocks.campaign.*;import mindustry.world.blocks.power.LightBlock;
import fpv.construction.*;import java.util.Arrays;

/** Native shipments and layered identities, not inferred inventory changes or synthetic resource output. */
public final class UtilityModelNativeTest {
    static int checks;static void check(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}
    static class Tex extends Texture{Tex(){super();width=height=64;}}
    public static void main(String[] args)throws Exception{
        ArcNativesLoader.load();mindustry.graphics.CacheLayer.init();LayerCampaignNativeTest.main(args);
        Core.gl=new MockGL20();Core.graphics=new MockGraphics();var pix=new Pixmap(32,32);pix.fill(0xa0a0a0ff);var region=new TextureAtlas.AtlasRegion(new Tex(),0,0,32,32);region.name="utility-fixture";Core.atlas=new TextureAtlas(){@Override public PixmapRegion getPixmap(TextureAtlas.AtlasRegion r){return new PixmapRegion(pix);}};Core.atlas.addRegion("white",region);
        Block[] types={Blocks.shockMine,Blocks.illuminator,Blocks.launchPad,Blocks.advancedLaunchPad,Blocks.landingPad};var owner=new LayerBuildingAdapter(null);var renderer=new UtilityModelRenderer();var batch=new NativeAtlasMesh.Builder(false);long id=800;
        try{
            for(var type:types){owner.clear();type.region=type.fullIcon=region;if(type instanceof LightBlock light)light.topRegion=region;System.out.println("Utility native "+type.name+" size="+type.size+" height="+FpvWorldRenderer.heightFor(type)+" class="+type.buildType.get().getClass().getName());
                for(int floor:new int[]{0,1,3,4,5})for(int rotation=0;rotation<4;rotation++){
                    var b=AdvancedLogisticsNativeTest.put(owner,id++,10+rotation*12,12+floor*8,floor,type,rotation);b.efficiency=1;
                    var far=UtilityModelGeometry.model(UtilityModelProfile.forBlock(type),type.size,2);check((far.body().length+far.lining().length+far.lights().length)/8<150,"far LOD drops subpixel arch/frame details");
                    for(int lod=0;lod<3;lod++){var g=UtilityModelGeometry.model(UtilityModelProfile.forBlock(type),type.size,lod);check(g==UtilityModelGeometry.model(UtilityModelProfile.forBlock(type),type.size,lod),"shared template");var before=LogisticsModelNativeTest.state(b);batch.clear();float h=FpvWorldRenderer.heightFor(type),base=floor*1.4f;check(renderer.render(b,batch,0,base,0,h,new float[]{0,900,10000}[lod]),"native XYZ/LOD body");var a=LogisticsModelNativeTest.vertices(batch);for(int i=0;i<a.length;i+=9){for(int j=0;j<9;j++)check(Float.isFinite(a[i+j]),"finite posed model");check(Math.abs(a[i])<=type.size*.501&&Math.abs(a[i+2])<=type.size*.501&&a[i+1]>=base-.001&&a[i+1]<base+h+.01,"unchanged physical body envelope");check(a[i+7]>=0&&a[i+7]<=.5&&a[i+8]>=0&&a[i+8]<=.5,"atlas-safe UV");}check(Arrays.equals(before,LogisticsModelNativeTest.state(b)),"draw cannot spend items/ship cargo/mutate native state");}
                }
            }
            check(renderer.entries()==5&&renderer.builds()==5,"all repeated instances reuse five native type caches");
            var light=(LightBlock.LightBuild)AdvancedLogisticsNativeTest.put(owner,id++,62,18,0,Blocks.illuminator,0);light.color=Color.cyan.rgba();light.efficiency=1;check(UtilityModelRenderer.level(light)==1,"native powered light");light.efficiency=0;check(UtilityModelRenderer.level(light)==0,"no powered light at zero efficiency");
            Vars.world.tile(12,68).setBlock(Blocks.launchPad,Team.sharded,0);var ground=(LaunchPad.LaunchPadBuild)Vars.world.build(12,68);var nativeType=(LaunchPad)ground.block;
            var state=new CampaignBeamState();state.begin(null);check(state.progress(ground)<0,"empty native pad never claims shipment");state.end();
            ground.items.set(Items.copper,ground.block.itemCapacity);ground.launchCounter=nativeType.launchTime;ground.efficiency=1;state.begin(null);check(state.progress(ground)<0,"charged full inventory alone is not a launched shipment");state.end();
            Time.delta=1;ground.updateTile();LaunchPayload payload=null;for(var e:Groups.all)if(e instanceof LaunchPayload p&&p.x==ground.x&&p.y==ground.y)payload=p;check(payload!=null&&ground.items.empty(),"real native pad creates payload and spends native resources once");state.begin(null);check(state.progress(ground)>=0,"actual full-to-empty launch matched to real cargo payload");state.end();payload.time=60;state.begin(null);check(Math.abs(state.progress(ground)-.5)<.001,"beam advances from real payload lifetime and freezes with it");state.end();payload.x+=8;state.begin(null);check(state.progress(ground)<0,"repositioned/reused cargo cannot animate previous source");state.end();payload.x-=8;payload.remove();state.begin(null);check(state.progress(ground)<0,"removed payload stops beam immediately");state.end();
            ground.items.set(Items.copper,ground.block.itemCapacity);ground.launchCounter=nativeType.launchTime;state.begin(null);state.progress(ground);state.end();ground.items.clear();ground.launchCounter=0;state.begin(null);check(state.progress(ground)<0,"inventory clearing/counter reset without cargo never fabricates launch");state.end();
            ground.items.set(Items.copper,ground.block.itemCapacity-1);ground.launchCounter=nativeType.launchTime;state.begin(null);state.progress(ground);state.end();ground.items.add(Items.copper,1);Time.delta=1;ground.updateTile();state.begin(null);check(state.progress(ground)>=0&&ground.items.empty(),"native last-item arrival can launch between frames without a full previous snapshot");state.end();
            var upper=(LaunchPad.LaunchPadBuild)owner.create(id++,52,60,4,Blocks.advancedLaunchPad,Team.sharded,0);upper.items.set(Items.copper,upper.block.itemCapacity);upper.launchCounter=((LaunchPad)upper.block).launchTime;upper.efficiency=1;Time.delta=1;upper.updateTile();check(state.progress(upper)==0,"existing upper launch evidence starts at correct layer");Time.delta=60;upper.updateTile();check(Math.abs(state.progress(upper)-.5)<.001,"existing replicated upper pod timer drives rising beam");
            var land=(LandingPad.LandingPadBuild)owner.create(id++,60,60,4,Blocks.landingPad,Team.sharded,0);var landingType=(LandingPad)land.block;land.config=Items.copper;land.liquids.add(landingType.consumeLiquid,landingType.consumeLiquidAmount);land.efficiency=1;Time.delta=1;check(state.progress(land)<0,"configured empty receiver is not an arrival");land.updateTile();check(land.arriving==Items.copper&&state.progress(land)==0,"real native landing starts downward beam");Time.delta=landingType.arrivalDuration*.5f;land.updateTile();check(Math.abs(state.progress(land)-.5)<.02,"receiver follows native arrival progress");Time.delta=landingType.arrivalDuration;land.updateTile();check(state.progress(land)<0&&land.items.get(Items.copper)==land.block.itemCapacity,"beam stops and actual cargo arrives exactly once");
            System.out.println("UtilityModelNativeTest: "+checks+" native templates/XYZ/UV/cache/color/read-only/actual launch and landing checks PASS; physical input separate");
        }finally{renderer.clear();batch.dispose();owner.clear();pix.dispose();}
    }
}
